import{_ as c,o as s,c as u}from"./chunks/framework.CTmd1Wj2.js";const m=JSON.parse(`{"title":"Linux 服务器常用运维命令","titleTemplate":":title · 知行笔记","description":"Linux服务器日常检查、文件管理、权限处理、SSH传输和故障排查的常用命令。 命令采用Bash写法，示例中的目录 /opt/demo 、用户 demo 和IP 192.0.2.10 按实际环境替换。安装软件、改权限、修改网络、停止服务和删","frontmatter":{"title":"Linux 服务器常用运维命令","titleTemplate":":title · 知行笔记","description":"Linux服务器日常检查、文件管理、权限处理、SSH传输和故障排查的常用命令。 命令采用Bash写法，示例中的目录 /opt/demo 、用户 demo 和IP 192.0.2.10 按实际环境替换。安装软件、改权限、修改网络、停止服务和删","kb":"{\\"site\\":{\\"title\\":\\"知行笔记\\",\\"description\\":\\"把实践整理成知识，让经验随时可查。\\",\\"publicRepository\\":\\"alcq77/alcq77.github.io\\",\\"localOnly\\":false,\\"support\\":{\\"wechat\\":\\"assets/support/wechat.jpg\\",\\"alipay\\":\\"assets/support/alipay.jpg\\"}},\\"docs\\":[{\\"id\\":\\"docker-compose-operations-commands\\",\\"title\\":\\"Docker 与 Docker Compose 常用运维命令\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"nginx-operations\\",\\"title\\":\\"Nginx 配置、部署与日常运维\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"ddd-design-practice\\",\\"title\\":\\"DDD 建模与落地实践\\",\\"module\\":\\"architecture\\",\\"category\\":\\"架构设计\\"},{\\"id\\":\\"kafka-operations\\",\\"title\\":\\"Kafka 部署、运维与故障排查\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kafka-internals\\",\\"title\\":\\"Kafka 核心机制与源码排查\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kafka-reliability\\",\\"title\\":\\"Kafka 消息生产、消费与可靠性实践\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kubernetes-operations-commands\\",\\"title\\":\\"Kubernetes 常用运维命令\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"kubernetes-cluster-troubleshooting\\",\\"title\\":\\"Kubernetes 集群搭建、维护与故障排查\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"kubernetes-application-practice\\",\\"title\\":\\"Kubernetes 应用部署与配置实践\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"linux-system-status-commands\\",\\"title\\":\\"Linux 常用系统状态查看命令\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-service-check-start-troubleshooting\\",\\"title\\":\\"Linux 服务检查、启动与排障\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-systemd-autostart\\",\\"title\\":\\"Linux 服务开机自启与 systemd 管理\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-server-operations-commands\\",\\"title\\":\\"Linux 服务器常用运维命令\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-kernel-troubleshooting\\",\\"title\\":\\"Linux 内核问题排查与处理\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-performance-troubleshooting\\",\\"title\\":\\"Linux 性能瓶颈排查与优化\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"}],\\"doc\\":{\\"id\\":\\"linux-server-operations-commands\\",\\"title\\":\\"Linux 服务器常用运维命令\\",\\"category\\":\\"Linux 运维\\"},\\"content\\":\\"\\\\u003cdiv class=\\\\\\"article-head\\\\\\">\\\\u003cdiv class=\\\\\\"eyebrow\\\\\\">Linux 运维\\\\u003c/div>\\\\u003ch1>Linux 服务器常用运维命令\\\\u003c/h1>\\\\u003cdiv class=\\\\\\"article-meta\\\\\\">\\\\u003cspan class=\\\\\\"author-avatar\\\\\\">知\\\\u003c/span>\\\\u003cspan>知行笔记\\\\u003c/span>\\\\u003cspan class=\\\\\\"meta-dot\\\\\\">·\\\\u003c/span>\\\\u003cspan>约 33 分钟阅读\\\\u003c/span>\\\\u003c/div>\\\\u003cdiv class=\\\\\\"tag-row\\\\\\">\\\\u003cspan class=\\\\\\"tag\\\\\\">linux\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">server\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">shell\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">ssh\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">files\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">permissions\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">network\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">operations\\\\u003c/span>\\\\u003c/div>\\\\u003c/div>\\\\u003carticle class=\\\\\\"markdown-body\\\\\\">\\\\u003cp>Linux服务器日常检查、文件管理、权限处理、SSH传输和故障排查的常用命令。\\\\u003c/p>\\\\n\\\\u003cp>命令采用Bash写法，示例中的目录 \\\\u003ccode>/opt/demo\\\\u003c/code>、用户 \\\\u003ccode>demo\\\\u003c/code> 和IP \\\\u003ccode>192.0.2.10\\\\u003c/code> 按实际环境替换。安装软件、改权限、修改网络、停止服务和删除文件等操作按需单独执行。\\\\u003c/p>\\\\n\\\\u003cdetails class=\\\\\\"install-guide\\\\\\">\\\\n\\\\u003csummary>命令不存在？展开查看常用工具安装方法\\\\u003c/summary>\\\\n\\\\u003cp>先确认系统，不要把不同发行版的命令整段一起执行：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /etc/os-release \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># ID和VERSION_ID用于确认系统\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">command\\\\u003c/span> -v \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> curl ss lsof iostat rg tmux \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看已安装命令\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：Ubuntu/Debian用apt，RHEL/Rocky/AlmaLinux等通常用dnf；旧系统可能只有yum。普通用户安装需要相应sudo授权，没有授权时请管理员操作。\\\\u003c/p>\\\\n\\\\u003ctable>\\\\n\\\\u003cthead>\\\\n\\\\u003ctr>\\\\n\\\\u003cth>命令\\\\u003c/th>\\\\n\\\\u003cth>Ubuntu / Debian 包名\\\\u003c/th>\\\\n\\\\u003cth>RHEL系常见包名\\\\u003c/th>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/thead>\\\\n\\\\u003ctbody>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>top、free、ps、pgrep、vmstat\\\\u003c/td>\\\\n\\\\u003ctd>procps\\\\u003c/td>\\\\n\\\\u003ctd>procps-ng\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>ip、ss\\\\u003c/td>\\\\n\\\\u003ctd>iproute2\\\\u003c/td>\\\\n\\\\u003ctd>iproute\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>lsblk、findmnt、lscpu、namei\\\\u003c/td>\\\\n\\\\u003ctd>util-linux\\\\u003c/td>\\\\n\\\\u003ctd>util-linux\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>iostat、pidstat\\\\u003c/td>\\\\n\\\\u003ctd>sysstat\\\\u003c/td>\\\\n\\\\u003ctd>sysstat\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>lsof\\\\u003c/td>\\\\n\\\\u003ctd>lsof\\\\u003c/td>\\\\n\\\\u003ctd>lsof\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>nc\\\\u003c/td>\\\\n\\\\u003ctd>netcat-openbsd\\\\u003c/td>\\\\n\\\\u003ctd>nmap-ncat\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>dig、nslookup\\\\u003c/td>\\\\n\\\\u003ctd>dnsutils\\\\u003c/td>\\\\n\\\\u003ctd>bind-utils\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>rg\\\\u003c/td>\\\\n\\\\u003ctd>ripgrep\\\\u003c/td>\\\\n\\\\u003ctd>ripgrep，可能需获准的附加仓库\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>mtr\\\\u003c/td>\\\\n\\\\u003ctd>mtr-tiny或mtr\\\\u003c/td>\\\\n\\\\u003ctd>mtr\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>其他\\\\u003c/td>\\\\n\\\\u003ctd>curl、wget、rsync、unzip、tmux、tcpdump、traceroute、openssl\\\\u003c/td>\\\\n\\\\u003ctd>通常同名\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/tbody>\\\\n\\\\u003c/table>\\\\n\\\\u003cp>Ubuntu / Debian按需选择软件包：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> apt-get update \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 刷新软件包索引\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> apt-get install sysstat lsof netcat-openbsd dnsutils ripgrep\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> apt-get install curl wget rsync unzip tmux tcpdump traceroute mtr-tiny openssl\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：只缺 \\\\u003ccode>iostat\\\\u003c/code> 时，刷新索引后只需 \\\\u003ccode>sudo apt-get install sysstat\\\\u003c/code>，不必安装整个列表。\\\\u003c/p>\\\\n\\\\u003cp>RHEL / Rocky / AlmaLinux按需选择软件包：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> dnf install sysstat lsof nmap-ncat bind-utils\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> dnf install curl wget rsync unzip tmux tcpdump traceroute mtr openssl\\\\ndnf info ripgrep \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 确认已批准的软件源是否提供ripgrep\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>rg\\\\u003c/code>不在现有仓库时可先用 \\\\u003ccode>grep -RnsE '关键词' /opt/demo\\\\u003c/code>。附加仓库由管理员按系统版本批准。\\\\u003c/p>\\\\n\\\\u003cp>CentOS 7：先检查已有仓库，再安装缺少的工具，下面两条安装命令也按需选择：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /etc/centos-release \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 确认是CentOS 7，其他发行版可能没有此文件\\\\u003c/span>\\\\nyum repolist           \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看当前启用仓库及可用包；可能需要访问软件源\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> yum install sysstat lsof nmap-ncat bind-utils \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># iostat/pidstat、文件占用、TCP与DNS检查\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> yum install curl wget rsync unzip tmux tcpdump traceroute mtr openssl \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 传输、终端及网络工具\\\\u003c/span>\\\\nyum provides \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;*/rg&#x27;\\\\u003c/span>     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查询现有批准仓库是否提供rg，不自动添加EPEL\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：只缺 \\\\u003ccode>ss\\\\u003c/code> 时安装 \\\\u003ccode>iproute\\\\u003c/code>；只缺 \\\\u003ccode>top/free/ps\\\\u003c/code> 时安装 \\\\u003ccode>procps-ng\\\\u003c/code>；只缺 \\\\u003ccode>findmnt/lsblk\\\\u003c/code> 时安装 \\\\u003ccode>util-linux\\\\u003c/code>。CentOS 7 的包名与上表RHEL列大多相同，具体以 \\\\u003ccode>yum provides '*/命令名'\\\\u003c/code> 查询结果为准。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003ca href=\\\\\\"https://www.centos.org/centos-linux/\\\\\\">CentOS 7已于2024年6月30日结束维护\\\\u003c/a>。这些步骤用于维护已有服务器，新部署选择仍受维护的系统。出现 \\\\u003ccode>Cannot find a valid baseurl\\\\u003c/code> 或镜像列表失效时，先核对DNS、网络及repo配置；原发行仓库已归档的情况由管理员提供批准的CentOS 7归档镜像或内部源。归档不提供持续安全更新，不改用Stream/Rocky的软件源、不关闭GPG/TLS校验，也不为了补工具执行整机升级。\\\\u003c/p>\\\\n\\\\u003cp>安装后验证：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">command\\\\u003c/span> -v iostat pidstat lsof nc dig rg tmux\\\\niostat -V\\\\nnc -h \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># netcat不同实现的选项会有区别\\\\u003c/span>\\\\nrg --version\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：安装sysstat使采样命令可用；是否开启长期历史采集是额外配置，不需要为了运行一次 \\\\u003ccode>iostat\\\\u003c/code> 就启动全部采集任务。安装不会在本文所述场景中自动配置目标业务服务。\\\\u003c/p>\\\\n\\\\u003c/details>\\\\n\\\\u003ch2 id=\\\\\\"普通用户登录后权限不足怎么处理\\\\\\">普通用户登录后，权限不足怎么处理\\\\u003c/h2>\\\\n\\\\u003ch3 id=\\\\\\"先确认当前身份和授权\\\\\\">先确认当前身份和授权\\\\u003c/h3>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">whoami\\\\u003c/span>    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前用户名\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">id\\\\u003c/span>        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 用户、主组和附加组\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> -l   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查询允许以sudo执行哪些命令，可能提示输入密码\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：SSH以 \\\\u003ccode>demo\\\\u003c/code> 登录，\\\\u003ccode>whoami\\\\u003c/code> 返回 \\\\u003ccode>demo\\\\u003c/code>。如果 \\\\u003ccode>sudo -l\\\\u003c/code> 显示允许执行某些 \\\\u003ccode>systemctl\\\\u003c/code> 命令，就只按授权范围使用；不代表可以执行所有管理员命令。\\\\u003c/p>\\\\n\\\\u003ctable>\\\\n\\\\u003cthead>\\\\n\\\\u003ctr>\\\\n\\\\u003cth>情况\\\\u003c/th>\\\\n\\\\u003cth>使用方法\\\\u003c/th>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/thead>\\\\n\\\\u003ctbody>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>有sudo授权\\\\u003c/td>\\\\n\\\\u003ctd>在需要权限的那一条命令前加 \\\\u003ccode>sudo\\\\u003c/code>\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>只允许部分命令\\\\u003c/td>\\\\n\\\\u003ctd>按 \\\\u003ccode>sudo -l\\\\u003c/code> 显示的命令和参数执行\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>没有sudo授权\\\\u003c/td>\\\\n\\\\u003ctd>请管理员执行，或授予具体命令/目录的必要权限\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>已获准使用root身份且有对应凭据\\\\u003c/td>\\\\n\\\\u003ctd>可按管理制度使用 \\\\u003ccode>su -\\\\u003c/code> 或已授权的 \\\\u003ccode>sudo -i\\\\u003c/code>\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>文件位于个人目录\\\\u003c/td>\\\\n\\\\u003ctd>通常直接操作，不需要sudo\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/tbody>\\\\n\\\\u003c/table>\\\\n\\\\u003cp>普通用户不能凭一条命令自行获得尚未授予的管理员权限。也不要为省事默认开放root远程登录或全量免密sudo。\\\\u003c/p>\\\\n\\\\u003ch3 id=\\\\\\"sudo-的常见用法\\\\\\">sudo 的常见用法\\\\u003c/h3>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl status demo-api --no-pager -l \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 用管理员权限查看服务\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl restart demo-api             \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 用管理员权限重启，会中断服务\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> journalctl -u demo-api -n 100 --no-pager \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 读取服务日志\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">ls\\\\u003c/span> -lah /root                          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 有授权时查看受限目录\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> -u demo \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">id\\\\u003c/span>                             \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 以指定用户执行，须被授权\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> -k                                    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 清除当前sudo认证缓存\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：普通用户 \\\\u003ccode>systemctl status\\\\u003c/code> 通常可用，但完整日志、其他用户的进程信息和启停操作可能需要提权。sudo通常要求输入\\\\u003cstrong>当前登录用户的密码\\\\u003c/strong>，不是root密码；具体取决于服务器策略。终端输入密码不显示字符是正常行为。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> -i  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 获准时进入root登录环境\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">whoami\\\\u003c/span>   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 核对是否为root\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">exit\\\\u003c/span>     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 完成后退出root shell，返回原用户\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：只执行一条管理命令时优先单条sudo。\\\\u003ccode>sudo -i\\\\u003c/code> 会改变身份、HOME和环境，完成后及时退出；再次 \\\\u003ccode>whoami\\\\u003c/code> 应回到原登录用户。\\\\u003ccode>su -\\\\u003c/code> 默认切换root，通常需要目标用户密码，目标账号锁定时可能不能使用。\\\\u003c/p>\\\\n\\\\u003ch3 id=\\\\\\"编辑配置与-shell-重定向\\\\\\">编辑配置与 shell 重定向\\\\u003c/h3>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">sudoedit /etc/systemd/system/demo-api.service \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 用获准的编辑方式修改配置\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl daemon-reload                 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 单元文件修改后重新加载\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>sudoedit\\\\u003c/code> 在策略允许时用当前用户的编辑器编辑临时副本，再以特权写回；可用范围取决于sudo授权。不要把配置文件永久改成普通用户所有来绕过编辑权限。\\\\u003c/p>\\\\n\\\\u003cp>下面这种写法可能仍然报 \\\\u003ccode>Permission denied\\\\u003c/code>：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">echo\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;example&#x27;\\\\u003c/span> &gt; /etc/demo.conf\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>echo\\\\u003c/code>被提权，但 \\\\u003ccode>&gt;\\\\u003c/code> 是当前普通用户的shell先执行的，写文件仍被拒绝。上面仅说明错误写法，不要尝试覆盖已有配置。\\\\u003c/p>\\\\n\\\\u003cp>这里的 \\\\u003ccode>&gt;\\\\u003c/code> 把标准输出写入文件，会覆盖原内容；\\\\u003ccode>&gt;&gt;\\\\u003c/code> 是在末尾追加。两者在目标文件不存在且目录权限允许时都会创建文件。\\\\u003c/p>\\\\n\\\\u003cp>如果确实要创建一个\\\\u003cstrong>新的演示文件\\\\u003c/strong>，可将输出交给有权限的 \\\\u003ccode>tee\\\\u003c/code>：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">printf\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;%s\\\\\\\\n&#x27;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;example&#x27;\\\\u003c/span> | \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">tee\\\\u003c/span> /etc/demo-example.conf &gt; /dev/null\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：权限作用在真正写文件的 \\\\u003ccode>tee\\\\u003c/code> 上。\\\\u003ccode>tee\\\\u003c/code> 默认覆盖文件，\\\\u003ccode>tee -a\\\\u003c/code> 才是追加；修改正式配置优先使用编辑器或受控发布，不能重复追加同一段配置。\\\\u003c/p>\\\\n\\\\u003cp>这条命令中，\\\\u003ccode>|\\\\u003c/code> 将 \\\\u003ccode>printf\\\\u003c/code> 的标准输出送给 \\\\u003ccode>tee\\\\u003c/code>；\\\\u003ccode>tee\\\\u003c/code> 写文件的同时也会把内容输出到终端，因此末尾 \\\\u003ccode>&gt; /dev/null\\\\u003c/code> 只丢弃这份标准输出，不影响前面的文件写入。\\\\u003ccode>/dev/null\\\\u003c/code> 可以理解为丢弃写入内容的特殊设备。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> sh -c \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;cd /root &amp;&amp; pwd&#x27;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 确有需要且获准时，在提权shell中执行内建命令\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>cd\\\\u003c/code> 是shell内建命令，\\\\u003ccode>sudo cd /root\\\\u003c/code>不能改变当前shell目录。通常无需进入受限目录，直接 \\\\u003ccode>sudo ls /root\\\\u003c/code> 更清楚；不要把不可信变量拼入 \\\\u003ccode>sh -c\\\\u003c/code>。\\\\u003c/p>\\\\n\\\\u003ch3 id=\\\\\\"上传文件先暂存再由管理员安装\\\\\\">上传文件先暂存，再由管理员安装\\\\u003c/h3>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">scp ./app.jar demo@192.0.2.10:~/app.jar.new \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 从本机上传到用户自己的目录\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：普通用户无法直接上传到root所有的发布目录时，先上传自己的HOME目录；SCP不能通过在远端路径前写sudo来提权。\\\\u003c/p>\\\\n\\\\u003cp>登录目标服务器后，在已安排的发版流程中执行：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sha256sum\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$HOME\\\\u003c/span>/app.jar.new&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 核对上传后的包\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl stop demo-api \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 停服并确认原进程退出后再替换\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> install -o demo -g demo -m 0644 \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$HOME\\\\u003c/span>/app.jar.new&quot;\\\\u003c/span> /opt/demo/app.jar\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl start demo-api\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：这里假设服务账号/组为 \\\\u003ccode>demo\\\\u003c/code>，且\\\\u003cstrong>原包已备份\\\\u003c/strong>。\\\\u003ccode>install\\\\u003c/code>会覆盖目标文件并设置属主和权限；实际账号、文件名与配置以服务为准，不直接复制到运行中的JAR上。\\\\u003c/p>\\\\n\\\\u003ch3 id=\\\\\\"服务目录与日志读取\\\\\\">服务目录与日志读取\\\\u003c/h3>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">ls\\\\u003c/span> -ld /opt/demo /opt/demo/logs \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 先检查属主和权限\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">tail\\\\u003c/span> -n 100 /opt/demo/logs/app.log \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 临时读取受限日志\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> ss -lntp \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;sport = :8080&#x27;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 完整查看端口对应进程\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：读取日志可以单条sudo，或由管理员通过专门的只读组/ACL授权。不应为了让维护账号看日志，把应用配置和数据目录全部开放写权限。journal读取权限通常可通过发行版对应日志组管理，但组名和授权范围需管理员核对。\\\\u003c/p>\\\\n\\\\u003ch3 id=\\\\\\"path环境变量和家目录变化\\\\\\">PATH、环境变量和家目录变化\\\\u003c/h3>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">command\\\\u003c/span> -v java                    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前普通用户解析到的Java\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> /opt/jdk17/bin/java -version  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 提权时使用已核对的绝对路径\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：sudo可能使用受控PATH、过滤环境变量，因此用户能执行 \\\\u003ccode>java\\\\u003c/code>，sudo却提示找不到，或执行了另一套版本。明确绝对路径，不为方便默认使用 \\\\u003ccode>sudo -E\\\\u003c/code> 保留全部环境。\\\\u003c/p>\\\\n\\\\u003cp>不要用sudo在用户项目里反复构建、解压或安装依赖，否则可能产生root所有的文件，后续普通用户无法修改。遇到这类问题先确认具体文件，再由管理员修复范围内的属主，不递归修改系统目录。\\\\u003c/p>\\\\n\\\\u003ch3 id=\\\\\\"常见报错对照\\\\\\">常见报错对照\\\\u003c/h3>\\\\n\\\\u003ctable>\\\\n\\\\u003cthead>\\\\n\\\\u003ctr>\\\\n\\\\u003cth>报错或现象\\\\u003c/th>\\\\n\\\\u003cth>处理\\\\u003c/th>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/thead>\\\\n\\\\u003ctbody>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>\\\\u003ccode>is not in the sudoers file\\\\u003c/code>\\\\u003c/td>\\\\n\\\\u003ctd>当前用户未被授予sudo，联系管理员\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>\\\\u003ccode>not allowed to execute\\\\u003c/code>\\\\u003c/td>\\\\n\\\\u003ctd>命令或参数不在授权范围，按最小范围申请\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>\\\\u003ccode>Authentication failure\\\\u003c/code>\\\\u003c/td>\\\\n\\\\u003ctd>核对当前用户密码、账号和sudo认证策略\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>sudo命令成功但 \\\\u003ccode>&gt;\\\\u003c/code> 报错\\\\u003c/td>\\\\n\\\\u003ctd>重定向仍由普通shell执行，用受控编辑或sudo tee\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>\\\\u003ccode>sudo: command not found\\\\u003c/code>\\\\u003c/td>\\\\n\\\\u003ctd>可能没有安装sudo；需管理员通过已授权途径处理\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>\\\\u003ccode>sudo java: command not found\\\\u003c/code>\\\\u003c/td>\\\\n\\\\u003ctd>核对sudo PATH，使用正确绝对路径\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>Docker socket \\\\u003ccode>permission denied\\\\u003c/code>\\\\u003c/td>\\\\n\\\\u003ctd>使用获准的sudo或rootless方案；docker组权限很高，不默认加入\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>\\\\u003ccode>kubectl Forbidden\\\\u003c/code>\\\\u003c/td>\\\\n\\\\u003ctd>查集群身份与RBAC，本机sudo不自动获得集群权限\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>改了Unix权限仍不能访问\\\\u003c/td>\\\\n\\\\u003ctd>核对父目录、ACL、SELinux、只读挂载和远程存储策略\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/tbody>\\\\n\\\\u003c/table>\\\\n\\\\u003cp>管理员若需配置sudo，应使用 \\\\u003ccode>visudo\\\\u003c/code> 或 \\\\u003ccode>visudo -f /etc/sudoers.d/指定文件\\\\u003c/code> 做语法校验，并保留可用管理会话；授权应限定必要命令与参数，不把“全部命令免密”作为默认配置。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"1-系统版本时间开机与负载\\\\\\">1. 系统版本、时间、开机与负载\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /etc/os-release \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 发行版和版本\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">uname\\\\u003c/span> -r            \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 内核版本\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">uname\\\\u003c/span> -m            \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># CPU架构\\\\u003c/span>\\\\nhostname            \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 主机名\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">date\\\\u003c/span>                \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 日期、时间、时区\\\\u003c/span>\\\\ntimedatectl         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 时间同步与时区状态\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">uptime\\\\u003c/span>              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 连续运行时间和1/5/15分钟负载\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">uptime\\\\u003c/span> -s           \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 最近开机时间\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">who\\\\u003c/span> -b              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 系统启动记录，依赖系统记录\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">nproc\\\\u003c/span>               \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前可用处理器数量\\\\u003c/span>\\\\nlscpu               \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># CPU详情\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：8核机器负载为 \\\\u003ccode>0.5 0.8 1.0\\\\u003c/code>，不代表CPU占用50%、80%、100%；负载还包含等待I/O等情况。时间不一致时先核对时区与同步，避免直接改时钟影响证书、任务调度和日志关联。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"2-cpu内存与实时观察\\\\\\">2. CPU、内存与实时观察\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">top                         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 实时查看进程\\\\u003c/span>\\\\nfree -h                     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 内存和swap，重点看available\\\\u003c/span>\\\\nvmstat 1 5                  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 1秒采样，共5次\\\\u003c/span>\\\\nps -eo pid,ppid,user,%cpu,%mem,\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">stat\\\\u003c/span>,etime,args --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sort\\\\u003c/span>=-%cpu | \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">head\\\\u003c/span> -n 15\\\\nps -eo pid,ppid,user,%cpu,%mem,\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">stat\\\\u003c/span>,etime,args --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sort\\\\u003c/span>=-%mem | \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">head\\\\u003c/span> -n 15\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>top\\\\u003c/code> 中按 \\\\u003ccode>P\\\\u003c/code> 排CPU、\\\\u003ccode>M\\\\u003c/code> 排内存、\\\\u003ccode>1\\\\u003c/code> 展开CPU，\\\\u003ccode>q\\\\u003c/code> 或通常 \\\\u003ccode>Ctrl+C\\\\u003c/code> 退出，只结束查看。\\\\u003ccode>free\\\\u003c/code> 中可回收缓存不是简单的“内存浪费”，不要为释放缓存随意清缓存。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003ccode>ps ... | head -n 15\\\\u003c/code> 中的 \\\\u003ccode>|\\\\u003c/code> 是管道，把左边命令的标准输出交给右边；这里表示只显示排序结果的前15行（包括表头），不修改原进程。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">iostat -xz 1 5   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 磁盘I/O，通常来自sysstat包\\\\u003c/span>\\\\npidstat -p 24680 1 5 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 指定进程采样，通常来自sysstat包\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：高负载但CPU不高时结合 \\\\u003ccode>vmstat\\\\u003c/code> 的等待进程、\\\\u003ccode>wa\\\\u003c/code> 与磁盘延迟分析。\\\\u003ccode>vmstat/iostat\\\\u003c/code> 首次输出常包含自开机以来的平均值，后续才是间隔采样。工具不存在时按发行版安装，不把“命令不存在”等同资源正常。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"3-当前目录与文件列表\\\\\\">3. 当前目录与文件列表\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">pwd\\\\u003c/span>                    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前绝对路径\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">ls\\\\u003c/span> -lah                \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 包含隐藏项、权限、大小\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">ls\\\\u003c/span> -lt                 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 按修改时间排序\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">stat\\\\u003c/span> /opt/demo/app.log \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 文件元数据\\\\u003c/span>\\\\nfile /opt/demo/app.jar \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 文件类型判断\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">readlink\\\\u003c/span> -f /opt/demo/current \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 解析符号链接实际目标\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：日志路径看起来相同但内容不对时，用 \\\\u003ccode>readlink -f\\\\u003c/code> 核对是否指向旧版本目录。\\\\u003ccode>ls -l\\\\u003c/code>显示的是文件逻辑大小，磁盘实际占用可用 \\\\u003ccode>du\\\\u003c/code> 查看。\\\\u003c/p>\\\\n\\\\u003cp>如果 \\\\u003ccode>ls -l\\\\u003c/code> 显示 \\\\u003ccode>current -&gt; /opt/demo/releases/v1\\\\u003c/code>，其中 \\\\u003ccode>-&gt;\\\\u003c/code> 表示左边的符号链接指向右边路径，是输出中的说明，不是Shell重定向命令；真正的输出重定向符是单独的 \\\\u003ccode>&gt;\\\\u003c/code>。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"4-创建复制移动与安全删除\\\\\\">4. 创建、复制、移动与安全删除\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">mkdir\\\\u003c/span> -p /opt/demo/backup           \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 创建目录，缺失父目录一起创建\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cp\\\\u003c/span> -a /opt/demo/conf /opt/demo/backup/conf-20261102 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 保留属性复制\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cp\\\\u003c/span> -i /opt/demo/app.jar /opt/demo/backup/app.jar   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 覆盖前询问\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">mv\\\\u003c/span> -i /opt/demo/app.jar.new /opt/demo/app.jar      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 移动/重命名，覆盖前询问\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：备份目录使用独立时间或版本名，防止覆盖上一份可用备份。\\\\u003ccode>cp -a\\\\u003c/code> 的目录目标已存在时可能形成嵌套目录，应先核对目标布局。\\\\u003c/p>\\\\n\\\\u003cp>删除前先看清对象：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">ls\\\\u003c/span> -ld -- /opt/demo/tmp/report.old \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 核对路径\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">rm\\\\u003c/span> -i -- /opt/demo/tmp/report.old  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 询问后删除单个文件\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">rmdir\\\\u003c/span> /opt/demo/tmp/empty-dir      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 仅删除空目录\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>--\\\\u003c/code> 结束选项解析，避免以减号开头的文件名被当作参数。删除目录树会连同内容一起移除，不能恢复为常规“回收站”；不把 \\\\u003ccode>rm -rf\\\\u003c/code>、通配符删除放进日常巡检流程。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"5-文件查找与内容搜索\\\\\\">5. 文件查找与内容搜索\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">find /opt/demo -\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">type\\\\u003c/span> f -name \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;*.log&#x27;\\\\u003c/span>           \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 按文件名查找\\\\u003c/span>\\\\nfind /opt/demo/logs -\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">type\\\\u003c/span> f -mtime +7 -\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">print\\\\u003c/span>  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 预览超过7天的文件\\\\u003c/span>\\\\nfind /opt/demo -\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">type\\\\u003c/span> f -size +100M -\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">print\\\\u003c/span>     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 大文件\\\\u003c/span>\\\\nrg -n \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;ERROR|Exception&#x27;\\\\u003c/span> /opt/demo/logs        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 带行号搜索，需ripgrep\\\\u003c/span>\\\\ngrep -nE \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;ERROR|Exception&#x27;\\\\u003c/span> /opt/demo/logs/app.log \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 无rg时使用grep\\\\u003c/span>\\\\ngrep -Rns --include=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;*.yaml&#x27;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;server:&#x27;\\\\u003c/span> /opt/demo/conf \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 递归查配置\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：先用 \\\\u003ccode>find ... -print\\\\u003c/code> 确认对象，不直接改为 \\\\u003ccode>-delete\\\\u003c/code>。\\\\u003ccode>-mtime +7\\\\u003c/code> 按24小时取整计算，不是“日历上7天之前”的精确分界。搜索配置可能看到密码，分享结果前脱敏。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">sed -n \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;100,150p&#x27;\\\\u003c/span> /opt/demo/logs/app.log \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 只打印100到150行\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">head\\\\u003c/span> -n 30 /opt/demo/logs/app.log       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 前30行\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">tail\\\\u003c/span> -n 100 /opt/demo/logs/app.log      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 最近100行\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">tail\\\\u003c/span> -F /opt/demo/logs/app.log          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 跟踪文件名，适合轮转后的日志\\\\u003c/span>\\\\nless /opt/demo/logs/app.log             \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 分页查看\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>less\\\\u003c/code> 中 \\\\u003ccode>/ERROR\\\\u003c/code> 搜索、\\\\u003ccode>n\\\\u003c/code> 下一个、\\\\u003ccode>Shift+N\\\\u003c/code> 上一个、\\\\u003ccode>q\\\\u003c/code> 退出。\\\\u003ccode>tail -F\\\\u003c/code> 按 \\\\u003ccode>Ctrl+C\\\\u003c/code> 只退出日志跟踪；不要推广到所有前台命令，前台服务可能会因此停止。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"6-压缩解压与校验\\\\\\">6. 压缩、解压与校验\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">tar -czf /opt/demo/backup/conf.tgz -C /opt/demo conf \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 相对路径归档\\\\u003c/span>\\\\ntar -tzf /opt/demo/backup/conf.tgz                  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 先列出归档内容\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">mkdir\\\\u003c/span> -p /opt/demo/restore-test                     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 准备空目录\\\\u003c/span>\\\\ntar -xzf /opt/demo/backup/conf.tgz -C /opt/demo/restore-test \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 解压\\\\u003c/span>\\\\nunzip -l /opt/demo/release.zip                      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看zip内容\\\\u003c/span>\\\\nunzip /opt/demo/release.zip -d /opt/demo/release-test \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 解压到单独目录\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sha256sum\\\\u003c/span> /opt/demo/app.jar                         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 哈希校验\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：归档里的 \\\\u003ccode>conf/...\\\\u003c/code> 解压到 \\\\u003ccode>restore-test/conf/...\\\\u003c/code>。先查看再解压，不对生产目录直接解压未知压缩包；源端与目标端SHA-256一致可确认传输内容一致，不代表来源可信。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"7-用户组与权限\\\\\\">7. 用户、组与权限\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">whoami\\\\u003c/span>                         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前用户\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">id\\\\u003c/span>                             \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前UID、GID与组\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">id\\\\u003c/span> demo                        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 指定用户身份\\\\u003c/span>\\\\ngetent passwd demo             \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查询系统用户信息\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">ls\\\\u003c/span> -ld /opt/demo /opt/demo/logs \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 目录权限与属主\\\\u003c/span>\\\\nnamei -l /opt/demo/logs/app.log \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 逐级查看路径权限，需工具可用\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> -l                        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前身份的sudo授权\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">umask\\\\u003c/span>                          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 新文件默认权限掩码\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：进程能读取文件却无法写日志，检查文件本身及所有父目录的访问权限、属主、只读挂载和SELinux，不直接递归开放全部权限。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">chown\\\\u003c/span> demo:demo /opt/demo/logs    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 调整指定目录属主，不递归\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">chmod\\\\u003c/span> 750 /opt/demo/logs         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 目录：属主全权限、组读和进入\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">chmod\\\\u003c/span> 640 /opt/demo/conf/app.yml \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 文件：属主读写、组只读\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">chmod\\\\u003c/span> u+x /opt/demo/bin/start.sh      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 给属主增加执行权限\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：目录的 \\\\u003ccode>x\\\\u003c/code> 表示可以进入/遍历，不等同普通文件的执行。改权限前确认服务实际运行用户；不用 \\\\u003ccode>chmod -R 777\\\\u003c/code> 作为通用修复。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"8-进程文件句柄与优雅停止\\\\\\">8. 进程、文件句柄与优雅停止\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">pgrep -af \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;demo-api.jar&#x27;\\\\u003c/span>                       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 完整命令行匹配\\\\u003c/span>\\\\nps -ww -p 24680 -o pid,ppid,user,\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">stat\\\\u003c/span>,etime,args \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 指定进程\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">readlink\\\\u003c/span> -f /proc/24680/exe               \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 可执行文件\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">readlink\\\\u003c/span> -f /proc/24680/cwd               \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 工作目录\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /proc/24680/limits                         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 进程实际限制\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">ulimit\\\\u003c/span> -n                                     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前shell文件描述符限制\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> lsof -p 24680                            \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 打开的文件，需lsof\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>ulimit -n\\\\u003c/code> 不是所有服务的实际限制，systemd服务应查其配置和对应 \\\\u003ccode>/proc/PID/limits\\\\u003c/code>。查询完整命令可能显示启动参数中的凭证，分享前脱敏。\\\\u003c/p>\\\\n\\\\u003cp>优先通过原管理器停止；仅对确认由手动启动的进程按需发信号：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">kill\\\\u003c/span> -TERM 24680              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 请求优雅退出\\\\u003c/span>\\\\nps -p 24680 -o pid,\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">stat\\\\u003c/span>,args \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 等待后确认是否退出，核对PID身份\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：SIGTERM允许应用清理连接和落盘。\\\\u003ccode>kill -KILL\\\\u003c/code> 不执行应用清理，只在无法正常退出且确认影响后使用；托管进程被直接杀死还可能由管理器拉起。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"9-磁盘inode挂载与删除未释放\\\\\\">9. 磁盘、inode、挂载与删除未释放\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">df\\\\u003c/span> -hT                       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 文件系统容量和类型\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">df\\\\u003c/span> -i                        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># inode使用量\\\\u003c/span>\\\\nlsblk -f                     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 块设备与文件系统\\\\u003c/span>\\\\nfindmnt                      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 挂载关系\\\\u003c/span>\\\\nfindmnt -T /opt/demo          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 指定路径所在挂载\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">du\\\\u003c/span> -xhd1 /var/log 2&gt;/dev/null \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 单文件系统内一级目录占用\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> lsof +L1                \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 已删除但仍被进程打开的文件\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>df\\\\u003c/code>显示满、\\\\u003ccode>du\\\\u003c/code>不大时，检查删除但仍打开的日志、被挂载遮盖的内容、权限范围和预留空间。inode耗尽时，小文件也无法新建。释放已删除文件需由相应进程关闭句柄，按业务方式重开日志或维护重启，不随意操作 \\\\u003ccode>/proc/PID/fd\\\\u003c/code>。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003ccode>2&gt;/dev/null\\\\u003c/code> 中的 \\\\u003ccode>2\\\\u003c/code> 表示标准错误，把权限不足等报错丢弃，正常结果仍显示；它只是隐藏报错，不会修复权限，也不表示目录统计完整。排障时需要看错误就去掉这一段。\\\\u003c/p>\\\\n\\\\u003cp>分区、格式化、扩容、卸载文件系统有数据与可用性影响，先确认设备、挂载、备份和具体文件系统方案，不使用一套命令盲目套用。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"10-网卡地址路由dns\\\\\\">10. 网卡、地址、路由、DNS\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">ip -br addr                           \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 网卡与IP\\\\u003c/span>\\\\nip \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">link\\\\u003c/span>                               \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 链路状态\\\\u003c/span>\\\\nip route                              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># IPv4路由\\\\u003c/span>\\\\nip -6 route                           \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># IPv6路由\\\\u003c/span>\\\\nip route get 192.0.2.10                \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 实际出口、源地址和路由\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /etc/resolv.conf                   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 解析器配置，可能由系统生成\\\\u003c/span>\\\\ngetent hosts example.com              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 按系统名称服务解析\\\\u003c/span>\\\\ndig example.com                       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># DNS查询，需dns工具\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>getent\\\\u003c/code>会遵循系统名称服务配置，可能命中hosts；\\\\u003ccode>dig\\\\u003c/code>主要查DNS，两者结果不一致时核对hosts、搜索域和解析器。不要直接覆盖由NetworkManager或systemd-resolved生成的文件。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"11-监听端口与连通性\\\\\\">11. 监听端口与连通性\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> ss -lntp                       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># TCP监听与进程\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> ss -lnup                       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># UDP监听与进程\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> ss -lntp \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;sport = :8080&#x27;\\\\u003c/span>        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 指定监听端口\\\\u003c/span>\\\\nss -s                              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># socket汇总\\\\u003c/span>\\\\nping -c 4 192.0.2.10               \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># ICMP可达性，可能被禁用\\\\u003c/span>\\\\nnc -vz -w 3 192.0.2.10 8080        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># TCP连接测试，参数随nc实现而异\\\\u003c/span>\\\\ncurl -i --connect-timeout 3 --max-time 5 http://192.0.2.10:8080/health\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：TCP连通只代表建立连接，HTTP401需看认证、404需看路径；\\\\u003ccode>/health\\\\u003c/code> 必须是实际存在的只读接口。\\\\u003ccode>127.0.0.1\\\\u003c/code>监听仅供本机访问，\\\\u003ccode>0.0.0.0\\\\u003c/code>是IPv4通配监听；IPv6通配是否也接收IPv4以系统和程序配置为准。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">traceroute 192.0.2.10 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 路由跳数诊断，需安装\\\\u003c/span>\\\\nmtr -rw -c 10 192.0.2.10 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 路径采样，可能需要权限\\\\u003c/span>\\\\nopenssl s_client -connect example.com:443 -servername example.com -verify_hostname example.com -verify_return_error &lt; /dev/null\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：中间跳不回应不一定代表业务丢包；TLS检查带正确SNI与主机名校验，并结合本机信任库检查证书链。不要用跳过证书校验作为长期修复。\\\\u003c/p>\\\\n\\\\u003cp>CentOS 7上的旧OpenSSL先用 \\\\u003ccode>openssl version\\\\u003c/code>、\\\\u003ccode>openssl s_client -help\\\\u003c/code> 核对选项；若不支持 \\\\u003ccode>-verify_hostname\\\\u003c/code>，HTTPS可用 \\\\u003ccode>curl -I --connect-timeout 3 --max-time 5 https://example.com/\\\\u003c/code> 检查证书链与域名。私有CA通过 \\\\u003ccode>--cacert /path/to/ca.pem\\\\u003c/code> 指定；不能仅删除主机名校验后把握手成功当作验证通过。TLS 1.3还要求程序和链接的TLS库支持。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003ccode>&lt; /dev/null\\\\u003c/code> 将标准输入接到空设备，程序读到的输入会立即结束，而不是继续等待键盘输入。\\\\u003ccode>&lt;\\\\u003c/code> 管输入，\\\\u003ccode>&gt;\\\\u003c/code> 管输出，方向不同。\\\\u003c/p>\\\\n\\\\u003cp>抓包需要授权与数据范围控制，文件可能包含业务或认证信息：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> tcpdump -i any -nn -c 50 \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;host 192.0.2.10 and tcp port 8080&#x27;\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：最多捕获50个匹配包，观察握手/重传等；\\\\u003ccode>-c\\\\u003c/code> 限制包数不限制等待时长，可用 \\\\u003ccode>Ctrl+C\\\\u003c/code> 提前结束。不要无过滤长时间抓取整个网卡流量。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"12-sshscp-与-rsync\\\\\\">12. SSH、SCP 与 rsync\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">ssh -p 22 demo@192.0.2.10                 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 登录\\\\u003c/span>\\\\nssh -i ~/.ssh/id_ed25519 demo@192.0.2.10 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 使用指定密钥\\\\u003c/span>\\\\nssh -v demo@192.0.2.10                    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 排查连接与认证\\\\u003c/span>\\\\nscp -P 22 ./app.jar demo@192.0.2.10:/opt/demo/releases/ \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 上传\\\\u003c/span>\\\\nscp -P 22 demo@192.0.2.10:/opt/demo/logs/app.log ./app.log \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 下载\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：SSH端口参数是小写 \\\\u003ccode>-p\\\\u003c/code>，SCP端口是大写 \\\\u003ccode>-P\\\\u003c/code>。首次连接核对服务器指纹，不默认关闭host key校验；\\\\u003ccode>ssh -v\\\\u003c/code>输出也可能暴露用户名与路径，分享前检查。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">rsync -av --dry-run ./release/ demo@192.0.2.10:/opt/demo/releases/ \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 预览\\\\u003c/span>\\\\nrsync -av ./release/ demo@192.0.2.10:/opt/demo/releases/           \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 同步\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：源目录尾部 \\\\u003ccode>/\\\\u003c/code> 表示复制其内容；没有尾部斜杠时目录层级可能不同。rsync需要相关端安装；不默认使用 \\\\u003ccode>--delete\\\\u003c/code>，它会删除目标端多出的文件。应用包先传暂存目录，不能直接边传边覆盖运行包。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"13-systemd-服务和日志\\\\\\">13. systemd 服务和日志\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">systemctl status demo-api --no-pager -l \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 服务状态\\\\u003c/span>\\\\nsystemctl is-active demo-api           \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 是否活动\\\\u003c/span>\\\\nsystemctl is-enabled demo-api          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 是否自启\\\\u003c/span>\\\\nsystemctl \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> demo-api --no-pager       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 文件及覆盖配置\\\\u003c/span>\\\\nsystemctl --failed --no-pager           \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 失败单元\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> journalctl -u demo-api -b -n 100 --no-pager \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 本次开机最近日志\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> journalctl -u demo-api --since \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;2026-11-02 10:00:00&#x27;\\\\u003c/span> --\\\\u003cspan class=\\\\\\"hljs-keyword\\\\\\">until\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;2026-11-02 10:10:00&#x27;\\\\u003c/span> --no-pager\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> journalctl -u demo-api -f          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 实时日志\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：按事故时间缩小日志范围，确保服务器时间与排查时间使用相同时区。\\\\u003ccode>active\\\\u003c/code>不替代业务检查；\\\\u003ccode>enabled\\\\u003c/code>不表示当前进程在运行。\\\\u003c/p>\\\\n\\\\u003cp>以下会更改状态，按需单独执行：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl start demo-api       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 启动\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl stop demo-api        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 停止\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl restart demo-api     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 重启，会中断业务\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl reload demo-api      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 仅服务实现了reload时可用\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">enable\\\\u003c/span> demo-api      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 开机自启，不立即启动\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">disable\\\\u003c/span> demo-api     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 关闭自启，不立即停止\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl daemon-reload        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 修改单元配置后重新读取\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：修改Nginx配置后先做 \\\\u003ccode>nginx -t\\\\u003c/code>，再按服务原管理方式reload；不是所有服务都支持reload。详细配置见 \\\\u003ca href=\\\\\\"linux-systemd-autostart.html\\\\\\">systemd自启与管理\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"14-内核oom登录与操作线索\\\\\\">14. 内核、OOM、登录与操作线索\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> journalctl -k -b -n 100 --no-pager          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 本次开机内核日志\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> journalctl -k -b --no-pager | grep -Ei \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;oom|out of memory|killed process|I/O error&#x27;\\\\u003c/span>\\\\nlast -x | \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">head\\\\u003c/span> -n 30                            \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 登录、关机、开机记录\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">who\\\\u003c/span>                                            \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前登录用户\\\\u003c/span>\\\\nw                                              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 用户与当前活动\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">history\\\\u003c/span> | \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">tail\\\\u003c/span> -n 50                            \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前shell历史\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：发现服务在SSH退出时停止，不能只凭时间相同断定有人关闭；需结合应用退出日志、内核OOM、信号、会话和审计记录。history可不完整、无时间或尚未写盘，不能作为完整责任认定依据。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003ccode>journalctl ... | grep ...\\\\u003c/code> 是把日志的标准输出交给 \\\\u003ccode>grep\\\\u003c/code> 筛选，\\\\u003ccode>last -x | head -n 30\\\\u003c/code> 则只展示前30行；普通 \\\\u003ccode>|\\\\u003c/code> 不会自动把左边命令的标准错误一起传过去。\\\\u003c/p>\\\\n\\\\u003cp>发行版常见认证日志：RHEL系可能为 \\\\u003ccode>/var/log/secure\\\\u003c/code>，Debian系可能为 \\\\u003ccode>/var/log/auth.log\\\\u003c/code>，也可能集中在journal。未提前启用审计时，通常无法事后完整还原每一次kill是谁发出的。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"15-cron-与系统定时器\\\\\\">15. cron 与系统定时器\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">crontab -l                      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前用户计划\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> crontab -u demo -l          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 指定用户计划\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">ls\\\\u003c/span> -l /etc/cron.d /etc/cron.daily \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 系统计划目录\\\\u003c/span>\\\\nsystemctl list-timers --all      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># systemd timers\\\\u003c/span>\\\\nsystemctl \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> demo-backup.timer demo-backup.service --no-pager \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看任务配置\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：查重复自启时同时检查用户cron、系统cron、systemd和应用自身调度。\\\\u003ccode>crontab -e\\\\u003c/code>会修改计划，\\\\u003ccode>crontab -r\\\\u003c/code>会删除整份计划，不当作查看命令。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-cron\\\\\\"># 每天02:30，以该crontab所属用户执行；目录需可写\\\\n30 2 * * * /bin/bash /opt/demo/bin/backup.sh &gt;&gt; /opt/demo/logs/backup.log 2&gt;&amp;1\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：cron环境比交互shell精简，脚本里使用绝对路径，明确PATH、工作目录、时区和锁；任务可能重叠，不能假设上一次一定已结束。标准crontab五个时间字段依次为分、时、日、月、星期。\\\\u003c/p>\\\\n\\\\u003cp>末尾 \\\\u003ccode>&gt;&gt; /opt/demo/logs/backup.log 2&gt;&amp;1\\\\u003c/code> 先把标准输出追加到日志，再让标准错误也写到同一位置，所以正常信息和报错都会保留。\\\\u003ccode>1\\\\u003c/code> 代表标准输出，\\\\u003ccode>2\\\\u003c/code> 代表标准错误；\\\\u003ccode>2&gt;&amp;1\\\\u003c/code> 中的 \\\\u003ccode>&amp;1\\\\u003c/code> 是文件描述符1，不是名为“1”的文件，也不是后台运行符。重定向按从左到右处理，不能随意调换顺序。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"16-软件包与命令位置\\\\\\">16. 软件包与命令位置\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">command\\\\u003c/span> -v java          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前PATH中的命令\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">type\\\\u003c/span> -a java             \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 所有解析结果，包含别名等\\\\u003c/span>\\\\njava -version            \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前实际Java版本\\\\u003c/span>\\\\nrpm -q curl              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># RHEL系查询包\\\\u003c/span>\\\\ndnf info curl            \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 新版RHEL系包信息\\\\u003c/span>\\\\ndpkg-query -W curl       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># Debian系查询包\\\\u003c/span>\\\\napt-cache policy curl    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># Debian系候选/已安装版本\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：按发行版选择rpm/dnf/yum或dpkg/apt，不能混用；自定义安装的Java、Nginx、Redis未必在系统包管理器里。\\\\u003c/p>\\\\n\\\\u003cp>缺少工具时，展开本文开头的“常用工具安装方法”，按发行版安装；不为一次排障直接执行整机软件升级。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"17-防火墙与-selinux\\\\\\">17. 防火墙与 SELinux\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">systemctl is-active firewalld        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># firewalld状态\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> firewall-cmd --get-active-zones \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 活动zone\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> firewall-cmd --zone=public --list-all \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 仅当实际zone为public\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> ufw status verbose             \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 使用ufw的系统\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> nft list ruleset               \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 使用nftables的系统\\\\u003c/span>\\\\ngetenforce                          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># SELinux模式，需系统启用相关工具\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">ls\\\\u003c/span> -Zd /opt/demo /opt/demo/logs      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># SELinux上下文\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：这些是不同防火墙管理方式，不要求都安装；按机器实际使用的工具查询。云安全组、负载均衡和Docker转发规则还要分别检查。排障不以关闭整个防火墙、停用SELinux作为默认方案。\\\\u003c/p>\\\\n\\\\u003cp>来源受限的firewalld运行时放行示例：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> firewall-cmd --zone=public \\\\\\\\\\\\n  --add-rich-rule=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;rule family=&quot;ipv4&quot; source address=&quot;192.0.2.20/32&quot; port port=&quot;8080&quot; protocol=&quot;tcp&quot; accept&#x27;\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：只在确认活动zone为public、授权来源为该IP时使用。运行时规则重载后可能丢失，验证有效后按同一规则增加 \\\\u003ccode>--permanent\\\\u003c/code> 持久化；更详细步骤见 \\\\u003ca href=\\\\\\"linux-service-check-start-troubleshooting.html\\\\\\">服务检查与排障\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"18-会话保持与后台作业\\\\\\">18. 会话保持与后台作业\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">tmux new -s ops            \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 创建会话，需安装tmux\\\\u003c/span>\\\\ntmux \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">ls\\\\u003c/span>                    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 会话列表\\\\u003c/span>\\\\ntmux attach -t ops         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 重新连接\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">jobs\\\\u003c/span> -l                    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前shell后台作业\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：tmux中按 \\\\u003ccode>Ctrl+B\\\\u003c/code> 后按 \\\\u003ccode>D\\\\u003c/code> 让会话继续运行并脱离；\\\\u003ccode>exit\\\\u003c/code>会结束当前shell，最后窗口结束后会话也结束。tmux用于交互维护，不代替长期服务的systemd管理。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003ccode>nohup\\\\u003c/code>、\\\\u003ccode>&amp;\\\\u003c/code>、\\\\u003ccode>disown\\\\u003c/code>、\\\\u003ccode>setsid\\\\u003c/code>解决的范围不同，不能自动保证开机恢复、应用健康或故障重启。部署服务优先采用已有管理机制。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"19-备份发版与重启前检查\\\\\\">19. 备份、发版与重启前检查\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">date\\\\u003c/span>                              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 记录当前时间\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">df\\\\u003c/span> -h                             \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 检查空间\\\\u003c/span>\\\\nsystemctl --failed --no-pager       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 已有失败服务\\\\u003c/span>\\\\nsystemctl is-enabled demo-api      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 核对自启\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sha256sum\\\\u003c/span> /opt/demo/releases/app.jar \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 新包校验\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：发版前备份原包、配置及必要数据，确认回滚兼容性；重启服务器前检查关键依赖、自启和远程恢复路径。重启后核对日志、端口、协议和关键业务，不能只看服务器能SSH登录。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl reboot \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 计划内重启整台服务器，会中断连接和服务\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：仅在已安排维护、确认影响后执行，不作为修复所有问题的第一步；数据库和有状态服务尤其要有一致性与恢复方案。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"20-常见问题速查\\\\\\">20. 常见问题速查\\\\u003c/h2>\\\\n\\\\u003ctable>\\\\n\\\\u003cthead>\\\\n\\\\u003ctr>\\\\n\\\\u003cth>现象\\\\u003c/th>\\\\n\\\\u003cth>先看什么\\\\u003c/th>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/thead>\\\\n\\\\u003ctbody>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>服务器很慢\\\\u003c/td>\\\\n\\\\u003ctd>uptime/top → vmstat → 内存 → I/O → 具体进程\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>磁盘满\\\\u003c/td>\\\\n\\\\u003ctd>df容量与inode → du → 删除未释放 → 日志/容器存储\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>端口不通\\\\u003c/td>\\\\n\\\\u003ctd>监听及归属 → 本机协议 → 路由 → 防火墙/安全组\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>服务突然退出\\\\u003c/td>\\\\n\\\\u003ctd>应用日志 → journal → 内核OOM → 管理器事件与审计\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>SSH断开后服务没了\\\\u003c/td>\\\\n\\\\u003ctd>原启动方式、终端信号、会话策略、进程管理\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>文件存在却Permission denied\\\\u003c/td>\\\\n\\\\u003ctd>用户/组 → 父目录权限 → 挂载 → SELinux\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>重启后配置不一致\\\\u003c/td>\\\\n\\\\u003ctd>实际单元 → WorkingDirectory → 环境与配置路径\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>日志时间对不上\\\\u003c/td>\\\\n\\\\u003ctd>系统时区、应用时区、日志格式、时间同步\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>改文件没生效\\\\u003c/td>\\\\n\\\\u003ctd>是否改到符号链接旧目标、容器挂载或另一套配置\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/tbody>\\\\n\\\\u003c/table>\\\\n\\\\u003cp>更短的状态速查见 \\\\u003ca href=\\\\\\"linux-system-status-commands.html\\\\\\">Linux系统状态查看\\\\u003c/a>。容器命令见 \\\\u003ca href=\\\\\\"docker-compose-operations-commands.html\\\\\\">Docker与Compose\\\\u003c/a>、\\\\u003ca href=\\\\\\"kubernetes-operations-commands.html\\\\\\">Kubernetes\\\\u003c/a>。各命令以本机 \\\\u003ccode>man\\\\u003c/code> 与 \\\\u003ccode>--help\\\\u003c/code> 为准。\\\\u003c/p>\\\\n\\\\u003c/article>\\\\u003cdiv class=\\\\\\"article-end\\\\\\">\\\\u003cspan>— 本文结束 —\\\\u003c/span>\\\\u003ca href=\\\\\\"../index.html\\\\\\">返回知识库首页 ↗\\\\u003c/a>\\\\u003c/div>\\",\\"toc\\":[{\\"title\\":\\"普通用户登录后，权限不足怎么处理\\",\\"level\\":2,\\"id\\":\\"普通用户登录后权限不足怎么处理\\"},{\\"title\\":\\"先确认当前身份和授权\\",\\"level\\":3,\\"id\\":\\"先确认当前身份和授权\\"},{\\"title\\":\\"sudo 的常见用法\\",\\"level\\":3,\\"id\\":\\"sudo-的常见用法\\"},{\\"title\\":\\"编辑配置与 shell 重定向\\",\\"level\\":3,\\"id\\":\\"编辑配置与-shell-重定向\\"},{\\"title\\":\\"上传文件先暂存，再由管理员安装\\",\\"level\\":3,\\"id\\":\\"上传文件先暂存再由管理员安装\\"},{\\"title\\":\\"服务目录与日志读取\\",\\"level\\":3,\\"id\\":\\"服务目录与日志读取\\"},{\\"title\\":\\"PATH、环境变量和家目录变化\\",\\"level\\":3,\\"id\\":\\"path环境变量和家目录变化\\"},{\\"title\\":\\"常见报错对照\\",\\"level\\":3,\\"id\\":\\"常见报错对照\\"},{\\"title\\":\\"1. 系统版本、时间、开机与负载\\",\\"level\\":2,\\"id\\":\\"1-系统版本时间开机与负载\\"},{\\"title\\":\\"2. CPU、内存与实时观察\\",\\"level\\":2,\\"id\\":\\"2-cpu内存与实时观察\\"},{\\"title\\":\\"3. 当前目录与文件列表\\",\\"level\\":2,\\"id\\":\\"3-当前目录与文件列表\\"},{\\"title\\":\\"4. 创建、复制、移动与安全删除\\",\\"level\\":2,\\"id\\":\\"4-创建复制移动与安全删除\\"},{\\"title\\":\\"5. 文件查找与内容搜索\\",\\"level\\":2,\\"id\\":\\"5-文件查找与内容搜索\\"},{\\"title\\":\\"6. 压缩、解压与校验\\",\\"level\\":2,\\"id\\":\\"6-压缩解压与校验\\"},{\\"title\\":\\"7. 用户、组与权限\\",\\"level\\":2,\\"id\\":\\"7-用户组与权限\\"},{\\"title\\":\\"8. 进程、文件句柄与优雅停止\\",\\"level\\":2,\\"id\\":\\"8-进程文件句柄与优雅停止\\"},{\\"title\\":\\"9. 磁盘、inode、挂载与删除未释放\\",\\"level\\":2,\\"id\\":\\"9-磁盘inode挂载与删除未释放\\"},{\\"title\\":\\"10. 网卡、地址、路由、DNS\\",\\"level\\":2,\\"id\\":\\"10-网卡地址路由dns\\"},{\\"title\\":\\"11. 监听端口与连通性\\",\\"level\\":2,\\"id\\":\\"11-监听端口与连通性\\"},{\\"title\\":\\"12. SSH、SCP 与 rsync\\",\\"level\\":2,\\"id\\":\\"12-sshscp-与-rsync\\"},{\\"title\\":\\"13. systemd 服务和日志\\",\\"level\\":2,\\"id\\":\\"13-systemd-服务和日志\\"},{\\"title\\":\\"14. 内核、OOM、登录与操作线索\\",\\"level\\":2,\\"id\\":\\"14-内核oom登录与操作线索\\"},{\\"title\\":\\"15. cron 与系统定时器\\",\\"level\\":2,\\"id\\":\\"15-cron-与系统定时器\\"},{\\"title\\":\\"16. 软件包与命令位置\\",\\"level\\":2,\\"id\\":\\"16-软件包与命令位置\\"},{\\"title\\":\\"17. 防火墙与 SELinux\\",\\"level\\":2,\\"id\\":\\"17-防火墙与-selinux\\"},{\\"title\\":\\"18. 会话保持与后台作业\\",\\"level\\":2,\\"id\\":\\"18-会话保持与后台作业\\"},{\\"title\\":\\"19. 备份、发版与重启前检查\\",\\"level\\":2,\\"id\\":\\"19-备份发版与重启前检查\\"},{\\"title\\":\\"20. 常见问题速查\\",\\"level\\":2,\\"id\\":\\"20-常见问题速查\\"}],\\"standaloneTitle\\":\\"\\"}"},"headers":[],"relativePath":"articles/linux-server-operations-commands.md","filePath":"articles/linux-server-operations-commands.md"}`),n={name:"articles/linux-server-operations-commands.md"};function a(e,l,t,p,o,d){return s(),u("div")}const r=c(n,[["render",a]]);export{m as __pageData,r as default};
